entries[137721] = { ["name"] = "Bauplan: Repetierbandagenflinte", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Repetierbandagenflinte herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Repetierbandagenflinte.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nRepetierbandagenflinte\nBenutzen: Heilt einen Verbündeten innerhalb von bis zu 40 Metern um ( 300 + 300 * 3) Gesundheit. (1 Min Abklingzeit)\n20 Aufladungen\nVerkaufspreis:\nBenötigt Leysteinerz (30), Schrotflinte des Teufelsgebrabbels , Echteisengewehrlauf" }
entries[137722] = { ["name"] = "Bauplan: Waffenpaket", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Waffenpaket herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Waffenpakets.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nWaffenpaket\nBenutzen: Schnallt Euch einige geladene Schusswaffen auf den Rücken. (15 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Leysteinerz (6), Schrotflinte des Teufelsgebrabbels (3), Anti-Höllenbestien-Raketenwerfer" }
entries[137723] = { ["name"] = "Bauplan: Automatikhammer", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Automatikhammer herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Automatikhammers.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nAutomatikhammer\nBenutzen: Stellt einen automatisierten Hammer auf, den alle nutzen können, um ihre Ausrüstung zu reparieren.\nVerkaufspreis:\nBenötigt Leysteinerz (15), Übergroße Sprengkapsel (10), Lockerer Abzug" }
entries[137724] = { ["name"] = "Bauplan: Fehlschlagdetektorpylon", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Fehlschlagdetektorpylon herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Fehlschlagdetektorpylonen.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nFehlschlagdetektorpylon\nBenutzen: Platziert einen elektrischen Pylonen auf dem Boden, der alle Gruppen- oder Schlachtzugsmitglieder innerhalb von 5 Metern nach dem Ende des Kampfes wiederbelebt.\n\nFunktioniert nicht bei Spielercharakteren ab Stufe 0 oder bei jenen, deren Geist freigelassen wurde. (3 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Teufelsschiefer (3), Chaosblaster (2)" }
entries[137725] = { ["name"] = "Bauplan: Akustischer Stimmungsverbesserer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen akustischen Stimmungsverbesserer herstellt.\nStellt einen akustischen Stimmungsverbesserer her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nAkustischer Stimmungsverbesserer\nBenutzen: Spielt Musik.\n\nIhr könnt die Musik ändern, indem Ihr Liederrollen einsetzt, die von Inschriftenkundigen gefertigt werden.\nVerkaufspreis:\nBenötigt Leysteinerz (50), Teufelsschiefer (50), Teufelswurz" }
entries[137726] = { ["name"] = "Bauplan: Leysteinboje", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Leysteinboje herstellt.\nStellt eine Leysteinboje her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nLeysteinboje\nBenutzen: Dies könnt Ihr nur unter Wasser benutzen. Besonders hilfreich, wenn Euch jeden Moment die Luft ausgeht.\nVerkaufspreis:\nBenötigt Leysteinerz (3)" }
entries[137727] = { ["name"] = "Bauplan: Mechanische Prägungsmatrix", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine mechanischen Prägungsmatrix herstellt.\nStellt eine mechanische Prägungsmatrix her.\nBenötigt Ingenieurskunst der Verheerten Inseln (1)\nVerkaufspreis:\nMechanische Prägungsmatrix\nKlassen: Jäger\nBenutzen: Gestattet es Euch, Haustiere aus der Mechanoidenfamilie zu zähmen und aufzuspüren.\nGestattet es Euch, Haustiere aus der Mechanoidenfamilie zu zähmen.\nZeigt alle mechanischen Einheiten in der Nähe auf der Minikarte an.\nVerkaufspreis:\nBenötigt Leysteinerz (5), Blut von Sargeras (20), Teufelswurz" }
entries[137728] = { ["name"] = "Technik: Schriftrolle des vergessenen Wissens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Schriftrolle des vergessenen Wissens herstellt.\nStellt eine Schriftrolle des vergessenen Wissens her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nSchriftrolle des vergessenen Wissens\nBenutzen: Lest die Schriftrolle und lernt etwas.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Rosenrote Pigmente (35)" }
entries[137729] = { ["name"] = "Technik: Kodex des ruhigen Gemüts", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Kodex des ruhigen Gemüts herstellt.\nStellt einen Kodex des ruhigen Gemüts her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nKodex des ruhigen Gemüts\nBenutzen: Stellt einen Kodex auf, der es Spielercharakteren in der Nähe gestattet, ihre Talente zu wechseln. Funktioniert nicht bei Zielen über Stufe 50.\n\"Wird von Spielercharakteren erstellt, die den Beruf Inschriftenkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:\nBenötigt Leichtes Pergament (50), Fahle Pigmente (5), Rosenrote Pigmente (25)" }
entries[137730] = { ["name"] = "Technik: Glyphe 'Geisterhaftes Verblassen'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Geisterhaftes Verblassen' herstellt.\nStellt eine Glyphe 'Geisterhaftes Verblassen' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Geisterhaftes Verblassen'\nKlassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr verblasst nun noch stärker in einen geisterhaften Zustand.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (2), Rosenrote Pigmente (70)" }
entries[137731] = { ["name"] = "Technik: Grimoire des Teufelswichtels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Grimoire des Teufelswichtels herstellt.\nStellt ein Grimoire des Teufelswichtels her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGrimoire des Teufelswichtels\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für den Teufelswichtel beim Barbier frei.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (15), Rosenrote Pigmente (5)" }
entries[137732] = { ["name"] = "Technik: Glyphe 'Glitzer'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Glitzer' herstellt.\nStellt eine Glyphe 'Glitzer' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Glitzer'\nKlassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer 'Langsamer Fall' hat jetzt mehr Glitzer.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (6), Rosenrote Pigmente (50)" }
entries[137733] = { ["name"] = "Technik: Glyphe 'Schwarz vor Augen'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Schwarz vor Augen' herstellt.\nStellt eine Glyphe 'Schwarz vor Augen' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Schwarz vor Augen'\nKlassen: Schurke\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEin guter Humpen voll setzt Ziele auch schnell außer Gefecht.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (10), Rosenrote Pigmente (30)" }
entries[137734] = { ["name"] = "Technik: Glyphe 'Wächtereule'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Wächtereule' herstellt.\nStellt eine Glyphe 'Wächtereule' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Wächtereule'\nKlassen: Druide\nBenutzen: Schaltet die Option für die Wächtereule als Fluggestalt beim Barbier frei.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)" }
entries[137735] = { ["name"] = "Technik: Glyphe 'Knisternder Kranichblitz'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Knisternder Kranichblitz' herstellt.\nStellt eine Glyphe 'Knisternder Kranichblitz' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Knisternder Kranichblitz'\nKlassen: Mönch\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eures Zaubers 'Knisternder Jadeblitz' hat nun die Farbe des Roten Kranichs. Exklusiv mit: Glyphe 'Knisternder Tigerblitz'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)" }
entries[137736] = { ["name"] = "Technik: Glyphe 'Spektralraptor'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Spektralraptor' herstellt.\nStellt eine Glyphe 'Spektralraptor' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Spektralraptor'\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert das Erscheinungsbild Eurer Geisterwolfgestalt ab, sodass Ihr einem großen Spektralraptoren ähnelt.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (6), Rosenrote Pigmente (50)" }
entries[137737] = { ["name"] = "Technik: Glyphe 'Sterneneruption'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Sterneneruption' herstellt.\nStellt eine Glyphe 'Sterneneruption' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Sterneneruption'\nKlassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr verschießt nun eine Sterneneruption, um den Zielort zu beleuchten. Exklusiv mit: Glyphe 'Goblinisches Antigravitationsleuchtfeuer'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)" }
entries[137738] = { ["name"] = "Technik: Glyphe 'Königin'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Königin' herstellt.\nStellt eine Glyphe 'Königin' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Königin'\nKlassen: Paladin\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Wächter der Uralten Könige beschwört nun den Zorn einer Königin herauf!\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (2), Rosenrote Pigmente (70)" }
