entries[137741] = { ["name"] = "Technik: Glyphe 'Teufelsberührte Seelen'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Teufelsberührte Seelen' herstellt.\nStellt eine Glyphe 'Teufelsberührte Seelen' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Teufelsberührte Seelen'\nKlassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure zerschmetterten Seelen sind mit Teufelsenergie befleckt. Exklusiv mit: Glyphe 'Manaberührte Seelen'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (12), Rosenrote Pigmente (20)" }
entries[137742] = { ["name"] = "Technik: Glyphe 'Knisternde Flamme'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Knisternde Flamme' herstellt.\nStellt eine Glyphe 'Knisternde Flamme' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Knisternde Flamme'\nKlassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer 'Feuerbrand' brennt mit weniger Teufelsenergie und sieht fast wie ein normales Feuer aus!\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (12), Rosenrote Pigmente (20)" }
entries[137743] = { ["name"] = "Technik: Glyphe 'Fahle Flügel'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Fahle Flügel' herstellt.\nStellt eine Glyphe 'Fahle Flügel' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Fahle Flügel'\nKlassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Gleiten aktiv ist, habt Ihr nun gelbe Flügel. Exklusiv mit: Glyphe 'Teufelsschwingen' Glyphe 'Zerfledderte Flügel'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (12), Rosenrote Pigmente (20)" }
