entries[137745] = { ["name"] = "Technik: Tarot der Prophezeiung", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Tarot der Prophezeiung herstellt.\nStellt ein Tarot der Prophezeiung her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nTarot der Prophezeiung\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\n+ 7 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 7.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (5), Rosenrote Pigmente (45)\nOptionale Reagenzien: [] (#47)" }
