entries[138009] = { ["name"] = "Muster: Machtgetränktes seidengewebtes Tuch", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein machtgetränktes seidengewebtes Tuch herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines machtgetränkten seidengewebten Tuchs.\nBenötigt Schneiderei der Verheerten Inseln (1)\nVerkaufspreis:\nMachtgetränktes seidengewebtes Tuch\nWird beim Anlegen gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nVerkaufspreis:\nBenötigt Machtgetränktes Seidengewebe (40), Runenfaden aus Katgut (4), Scharfer Waldgeistdorn , Blut von Sargeras (2)" }
entries[138010] = { ["name"] = "Muster: Machtgetränktes seidengewebtes Tuch", ["text"] = "Rang 3\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein machtgetränktes seidengewebtes Tuch herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines machtgetränkten seidengewebten Tuchs.\nBenötigt Schneiderei der Verheerten Inseln (1)\nVerkaufspreis:\nMachtgetränktes seidengewebtes Tuch\nWird beim Anlegen gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nVerkaufspreis:\nBenötigt Machtgetränktes Seidengewebe (35), Runenfaden aus Katgut (4), Scharfer Waldgeistdorn , Blut von Sargeras (2)" }
entries[138011] = { ["name"] = "Muster: Seidengewebter Ranzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen seidengewebten Ranzen herstellt.\nStellt einen seidengewebten Ranzen her.\nBenötigt Schneiderei der Verheerten Inseln (1)\nVerkaufspreis:\nSeidengewebter Ranzen\nWird beim Anlegen gebunden\n24 Platz Tasche\nVerkaufspreis:\nBenötigt Shal'doreiseide (90)" }
entries[138012] = { ["name"] = "Muster: Seidengewebte Handschuhe", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man seidengewebte Handschuhe herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung seidengewebter Handschuhe.\nBenötigt Schneiderei der Verheerten Inseln (1)\nVerkaufspreis:\nSeidengewebte Handschuhe\nWird beim Anlegen gebunden\nHände Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nHaltbarkeit 50 / 50\nVerkaufspreis:\nBenötigt Shal'doreiseide (12), Runenfaden aus Katgut (3)\nOptionale Reagenzien: [] (#49)" }
entries[138013] = { ["name"] = "Muster: Seidengewebte Kapuze", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine seidengewebten Kapuze herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer seidengewebten Kapuze.\nBenötigt Schneiderei der Verheerten Inseln (1)\nVerkaufspreis:\nSeidengewebte Kapuze\nWird beim Anlegen gebunden\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Shal'doreiseide (16), Runenfaden aus Katgut , Scharfer Waldgeistdorn\nOptionale Reagenzien: [] (#48)" }
entries[138014] = { ["name"] = "Muster: Seidengewebte Pantoffeln", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man seidengewebte Pantoffeln herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung seidengewebter Pantoffeln.\nBenötigt Schneiderei der Verheerten Inseln (1)\nVerkaufspreis:\nSeidengewebte Pantoffeln\nWird beim Anlegen gebunden\nFüße Stoff\n3 Rüstung\n+4 Intelligenz\n+5 Ausdauer\nHaltbarkeit 65 / 65\nVerkaufspreis:\nBenötigt Shal'doreiseide (12), Runenfaden aus Katgut\nOptionale Reagenzien: [] (#48)" }
entries[138015] = { ["name"] = "Muster: Seidengewebte Pantalons", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man seidengewebte Pantalons herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung seidengewebter Pantalons.\nBenötigt Schneiderei der Verheerten Inseln (1)\nBenötigt Farondis' Hofstaat\n- Wohlwollend\nVerkaufspreis:\nSeidengewebte Pantalons\nWird beim Anlegen gebunden\nBeine Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Shal'doreiseide (16), Runenfaden aus Katgut (2), Scharfer Waldgeistdorn\nOptionale Reagenzien: [] (#48)" }
entries[138016] = { ["name"] = "Kleidertruhenmuster: Einwohner von Dalaran", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Kleidertruhe: Einwohner von Dalaran herstellt.\nStellt eine Kleidertruhe her, die Kostüme der Einwohner von Dalaran enthält.\nBenötigt Schneiderei der Verheerten Inseln (1)\nVerkaufspreis:\nKleidertruhe: Einwohner von Dalaran\nBenutzen: Stellt eine Kleidertruhe auf, damit Eure Schlachtzugs- oder Gruppenmitglieder etwas anprobieren können.\nVerkaufspreis:\nBenötigt Shal'doreiseide (50)" }
entries[138017] = { ["name"] = "Kleidertruhenmuster: Oper von Karazhan", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Kleidertruhe: Oper von Karazhan herstellt.\nStellt eine Kleidertruhe her, die Kostüme der Oper von Karazhan enthält.\nBenötigt Schneiderei der Verheerten Inseln (1)\nVerkaufspreis:\nKleidertruhe: Oper von Karazhan\nBenutzen: Stellt eine Kleidertruhe auf, damit Eure Schlachtzugs- oder Gruppenmitglieder etwas anprobieren können.\nVerkaufspreis:\nBenötigt Shal'doreiseide (40), Netherstoffballen" }
entries[138018] = { ["name"] = "Kleidertruhenmuster: Geschmolzener Kern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Kleidertruhe: Geschmolzener Kern herstellt.\nStellt eine Kleidertruhe her, die Kostüme aus dem Geschmolzenen Kern enthält.\nBenötigt Schneiderei der Verheerten Inseln (1)\nVerkaufspreis:\nKleidertruhe: Geschmolzener Kern\nBenutzen: Stellt eine Kleidertruhe auf, damit Eure Schlachtzugs- oder Gruppenmitglieder etwas anprobieren können.\nVerkaufspreis:\nBenötigt Shal'doreiseide (50), Runenstoffballen" }
entries[138019] = { ["name"] = "Mythischer Schlüsselstein", ["text"] = "Wird beim Aufheben gebunden\n\"Setzt ihn im Dungeon auf dem Schwierigkeitsgrad 'Mythisch' im Born der Macht ein.\"" }
entries[138020] = { ["name"] = "Fleischige Moschusrippchen am Stück", ["text"] = "Questgegenstand\n\"Das Beste, was die Grillkunst der Vrykul zu bieten hat.\"" }
entries[138021] = { ["name"] = "Büschel feinstes Ziegenhaar", ["text"] = "Questgegenstand\n\"Daraus könnte man einen schönen Pullover herstellen.\"" }
entries[138022] = { ["name"] = "Hassfeders Schnabel", ["text"] = "Questgegenstand\n\"Das Ding hier hätte beinahe einen Finger abgerissen.\"" }
entries[138023] = { ["name"] = "Steinzahns Kiefer", ["text"] = "Questgegenstand\n\"Bei genauerer Betrachtung stellt sich heraus, dass die Zähne wohl doch nicht aus Stein sind.\"" }
entries[138024] = { ["name"] = "Stahlschuppes Flosse", ["text"] = "Questgegenstand\n\"Aus einer Flosse dieser Größe könnte man eine Menge Suppe kochen.\"" }
entries[138026] = { ["name"] = "Machterfülltes Ladegerät", ["text"] = "Einzigartig\nBenutzen: Feuert eine explosive Energieladung auf ein inaktives Fahrzeug innerhalb von 30 Metern.\n\"Seltsamerweise geht von ihm ständig ein leises Summen aus.\"" }
entries[138027] = { ["name"] = "Portalschlüssel: Station der Kanalwächter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Offenbart das Schattenseitenportal in der Nähe der Station der Kanalwächter." }
entries[138028] = { ["name"] = "Portalschlüssel: Schwarzmarkt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Offenbart das Schattenseitenportal in der Nähe des Schwarzmarkts." }
entries[138029] = { ["name"] = "Portalschlüssel: Eingang des Gasthauses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Offenbart das Schattenseitenportal in der Nähe des Eingangs zum Gasthaus." }
entries[138030] = { ["name"] = "Portalschlüssel: Versteck der Alchemisten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Offenbart das Schattenseitenportal im Versteck der Alchemisten." }
entries[138031] = { ["name"] = "Portalschlüssel: Verlassene Hütte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Offenbart das Schattenseitenportal in der Nähe des verlassenen Schuppens." }
entries[138032] = { ["name"] = "Portalschlüssel: Hintereingang", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Offenbart das Schattenseitenportal in der Nähe des Hintereingangs." }
entries[138033] = { ["name"] = "Schriftrolle der Befehlsgewalt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\nBenutzen: Liest ein Edikt aus der Schriftrolle der Befehlsgewalt und unterwirft für 2 Min. einen Dämon Eurem Willen. (1 Min Abklingzeit)" }
entries[138084] = { ["name"] = "Schmiedeeisernes Eroberungsinsigne", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\n+ 6 Vielseitigkeit\nAnlegen: Wenn Ihr Schaden verursacht, besteht eine Chance, dass Eure Beweglichkeit 20 Sek. lang um 12 erhöht wird.\nVerkaufspreis:" }
entries[138090] = { ["name"] = "Schmiedeeisernes Vorherrschaftsinsigne", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\n+ 6 Vielseitigkeit\nAnlegen: Wenn Ihr Schaden verursacht oder ein Ziel heilt, besteht eine Chance, dass Eure Intelligenz 20 Sek. lang um 12 erhöht wird.\nVerkaufspreis:" }
entries[138093] = { ["name"] = "Schmiedeeisernes Siegesinsigne", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nAnlegen: Wenn Ihr Schaden verursacht, besteht eine Chance, dass Eure Stärke 20 Sek. lang um 12 erhöht wird.\nVerkaufspreis:" }
entries[138097] = { ["name"] = "Rußschmieds Energiekern", ["text"] = "Wird beim Aufheben gebunden\n\"Das gute Stück wird er nicht mehr brauchen.\"\nVerkaufspreis:" }
entries[138098] = { ["name"] = "Eisengebundene Kiste mit Schlachtfeldbeute", ["text"] = "Wird beim Aufheben gebunden\nDauer: 3 tagen\n\"Kann ein Ausrüstungsteil enthalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[138099] = { ["name"] = "Himmelsfeuerstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nDauer: 1 Stunde (Realzeit)\nBenutzen: Beschwört einen Teufelsmeteor auf einen Zielort hinab, der Feuerschaden verursacht und alle Gegner innerhalb von 10 Metern betäubt. (1 Min Abklingzeit)" }
entries[138100] = { ["name"] = "\"Ab die Pest\"-Bombe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nDauer: 1 Stunde (Realzeit)\nBenutzen: Wirft eine Pestbombe, die eine Gaswolke erzeugt, die pro Sekunde 2 Naturschaden verursacht und die Bewegungsgeschwindigkeit von Gegnern innerhalb ihres Effektbereichs um 50% verringert. (1 Min Abklingzeit)" }
entries[138102] = { ["name"] = "Verschlüsselte Nachricht", ["text"] = "Questgegenstand\nBenutzen: Nutzt den dämonischen Codeschlüssel, um den Inhalt der Nachricht zu entschlüsseln. (30 Sek. Abklingzeit)" }
entries[138111] = { ["name"] = "Sturmgeschmiedeter Greifhakenwerfer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\n\"Wird benutzt, um Greifhakenziele in ganz Sturmheim zu erreichen.\"" }
entries[138112] = { ["name"] = "Schädel des Unschuldigen", ["text"] = "Questgegenstand\n\"Machtvolle dämonische Rituale bedürfen hin und wieder des unversehrten Schädels einer reinen Seele.\"" }
entries[138113] = { ["name"] = "Blut des Unschuldigen", ["text"] = "Questgegenstand\n\"Nur die finsterste Magie bedarf des Bluts der wahrhaftig Unschuldigen.\"" }
entries[138114] = { ["name"] = "Dämmerfrenzy", ["text"] = "Das Dämmernde Riff\nWird beim Aufheben gebunden\n\"Ein Albinofrenzy mit rasiermesserscharfen Zähnen. Ist selten am Dämmernden Riff zu finden.\"" }
entries[138115] = { ["name"] = "Kalecs Abbildkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört für 30 Sek. ein Abbild von Kalec. (30 Sek. Abklingzeit)" }
entries[138116] = { ["name"] = "Wurffackel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nDauer: 10 min (Realzeit)\nBenutzen: Wirft mit der Fackel nach einem Gegner und fügt ihm Feuerschaden zu. Gegner in der Nähe, die mit dem Effekt 'Grogdurchnässt' belegt sind, werden in Brand gesteckt. (1 Min Abklingzeit)" }
entries[138117] = { ["name"] = "Spirituelle Reise", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Schamane\nAnlegen: In Geisterwolfgestalt wird die verbleibende Abklingzeit von 'Wildgeister' um 500% schneller abgeschlossen.\n\"Um den Wolf zu beherrschen, muss man SELBST zum Wolf werden! - Rat eines wahnsinnigen Vrykulschamanen\"\nVerkaufspreis:" }
entries[138120] = { ["name"] = "Schwester Lilith", ["text"] = "Wird beim Aufheben gebunden\n\"Schwester Lilith kommt in den Hain der Träume und ermöglicht es Euch, Treants des Hains der Träume zu rekrutieren, die Eure Champions auf Missionen begleiten.\"" }
entries[138121] = { ["name"] = "Beschriebenes Blatt der Weisheit", ["text"] = "Wird beim Aufheben gebunden\n\"Blattbart der Erzähler ermöglicht es Euch, Forschung für den Aufstiegsbaum des Ordens durchzuführen.\"" }
entries[138123] = { ["name"] = "Glänzendes Goldnugget", ["text"] = "Wird beim Aufheben gebunden\n\"Es scheint nicht sehr viel zu wiegen.\"" }
entries[138124] = { ["name"] = "Goldbemalter Stein", ["text"] = "Wird beim Aufheben gebunden\n\"So, wie die Farbe glänzt, könnte man schwören, dass es sich um echtes Gold handelt!\"\nVerkaufspreis:" }
entries[138125] = { ["name"] = "Kristallklarer Edelstein", ["text"] = "Wird beim Aufheben gebunden\n\"Er fühlt sich eiskalt an.\"" }
entries[138126] = { ["name"] = "Teilweise geschmolzener Eisbrocken", ["text"] = "Wird beim Aufheben gebunden\n\"Das würde die Temperatur erklären.\"\nVerkaufspreis:" }
entries[138127] = { ["name"] = "Rätselhafte Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Sie kommt Euch irgendwie bekannt vor.\"" }
entries[138128] = { ["name"] = "Eine alte Münze der Venture Co.", ["text"] = "Wird beim Aufheben gebunden\n\"Die sind heutzutage nichts mehr wert!\"\nVerkaufspreis:" }
entries[138129] = { ["name"] = "Fetzen unbezahlbarer Seide", ["text"] = "Wird beim Aufheben gebunden\n\"Fühlt sich weich an, hat aber einen schwachen Eigengeruch.\"" }
entries[138130] = { ["name"] = "Stück eines alten Goblinhemds", ["text"] = "Wird beim Aufheben gebunden\n\"Der Palmendruck sagt doch eigentlich schon alles.\"\nVerkaufspreis:" }
entries[138131] = { ["name"] = "Magisch aufkeimende Bohnen", ["text"] = "Wird beim Aufheben gebunden\n\"Nach dem Pflanzen müssten die Bohnenstangen bis in den Himmel wachsen!\"" }
entries[138132] = { ["name"] = "Ganz normale Bohnen", ["text"] = "Wird beim Aufheben gebunden\n\"Was habt Ihr erwartet?\"\nVerkaufspreis:" }
entries[138133] = { ["name"] = "Elixier der endlosen Wunder", ["text"] = "Wird beim Aufheben gebunden\n\"Man sagt, es würde denjenigen, der es trinkt, mit Wunderkräften und Weisheit erfüllen.\"" }
entries[138134] = { ["name"] = "Phiole mit fragwürdiger Flüssigkeit", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr seid ziemlich sicher, dass es sich um Goblinurin handelt.\"\nVerkaufspreis:" }
entries[138135] = { ["name"] = "Rax' Lupe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Nehmt die Qualität von Rax' \"schönsten Waren\" genau unter die Lupe." }
entries[138136] = { ["name"] = "Panzer der klaren Sprache", ["text"] = "Questgegenstand\nEinzigartig\n\"Teil eines Muschelpaares, das alle Geräusche von einem Ende zum anderen überträgt.\"" }
entries[138137] = { ["name"] = "Hauptmann Hjalmar Stahlstrom", ["text"] = "Wird beim Aufheben gebunden\n\"Hauptmann Hjalmar Stahlstrom kommt in die Hallen der Tapferkeit und ermöglicht es Euch, Aspiranten der Valarjar zu rekrutieren, die Eure Champions auf Missionen begleiten.\"" }
entries[138138] = { ["name"] = "Einar der Runenmagier", ["text"] = "\"Einar der Runenmagier kommt in Eure Ordenshalle und ermöglicht es Euch, Forschung für den Aufstiegsbaum des Ordens durchzuführen.\"" }
entries[138139] = { ["name"] = "Grimoire der arkanen Herangehensweisen", ["text"] = "Questgegenstand\n\"Mit dem magischen Wissen aus diesem Buch kann Matronenmutter Malicia die heilige Barriere durchdringen, die eine Teleportation in den Schwarzen Tempel verhindert.\"" }
entries[138140] = { ["name"] = "Magtheridons verbannte Armschienen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Magier\nAnlegen: Euer Zauber 'Eislanze' erhöht 8 Sek. lang den Schaden Eurer Eislanzen um 3%. Dieser Effekt ist bis zu 6-mal stapelbar.\n\"Durch Verwendung eines Manticronwürfels werden diese Dinger manchmal nutzlos.\"\nVerkaufspreis:" }
entries[138142] = { ["name"] = "Ojin'bas Kopf", ["text"] = "Questgegenstand\n\"Der abgetrennte Kopf von Ojin'ba, dem Anführer der Trolle der Bleichborken.\"" }
entries[138146] = { ["name"] = "Strahlender Leykristall", ["text"] = "Questgegenstand\nBenutzen: Verwendet dies, um einen verwundeten blauen Drachen wiederzubeleben." }
entries[138147] = { ["name"] = "Kontrollkugel", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Hauch einer Berührung reicht aus, um Barrieren in der Nähe nach Belieben zu aktivieren oder zu deaktivieren.\"" }
entries[138148] = { ["name"] = "Trol'kalar", ["text"] = "Questgegenstand\nEinzigartig\n\"Die legendäre Klinge der Familie Trollbann, die seit Generationen weitergegeben wird.\"" }
entries[138149] = { ["name"] = "Uralte Schrifttafel von Dreyrgrot", ["text"] = "Questgegenstand\n\"Die Vrykulsymbole auf dieser Steintafel sehen wie Warnzeichen aus.\"" }
entries[138150] = { ["name"] = "Bruchzahns Rubinamulett", ["text"] = "Questgegenstand\n\"Das Licht bricht sich in dem Kristall auf eine Weise, die ihn fast flüssig erscheinen lässt.\"" }
entries[138151] = { ["name"] = "Kiste mit uralten Relikten", ["text"] = "Questgegenstand\n\"Sie mag nicht viel wert sein, aber sie könnte einen unermesslichen Schatz an Wissen enthalten.\"" }
