entries[138201] = { ["name"] = "Tiefenbewohner", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Tiefenbewohner oder gibt ihn wieder frei.\n\nLässt sich nur unter Wasser einsetzen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Tief in den unwirtlichen Gräben des Großen Meeres schweben blinde Schwärme der Tiefenbewohner wie ein dichter Teppich durch das Wasser.\"\nBeute von:\nKosumoth der Hungernde" }
