entries[138225] = { ["name"] = "Phantomhaftes Echo", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nAnlegen: Wenn Eure Gesundheit unter 50% fällt, manifestiert sich eine Schattenreflexion aus dem Smaragdgrünen Alptraum, die für 20 Sek. 50% des erlittenen Schadens absorbiert. Verhindert insgesamt bis zu 3246 Schaden. Dieser Effekt kann nur ein Mal alle 2 Min. auftreten. (2Min. Abklingzeit)\nVerkaufspreis:" }
entries[138226] = { ["name"] = "In Alpträume gehülltes Juwel", ["text"] = "Wird beim Aufheben gebunden\nSchatten Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
entries[138227] = { ["name"] = "Bezaubernder Stein", ["text"] = "Wird beim Aufheben gebunden\nArkan Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
entries[138228] = { ["name"] = "Biolumineszenter Pilz", ["text"] = "Wird beim Aufheben gebunden\nLeben Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
entries[138229] = { ["name"] = "Alptraum- Boss 3 - Relikt STURM", ["text"] = "Wird beim Aufheben gebunden\nSturm Artefaktrelikt\n+ 16 Gegenstands-Level\nVerkaufspreis:" }
entries[138231] = { ["name"] = "Schlachtenfürst Gaardoun", ["text"] = "\"Schlachtenfürst Gaardoun kommt auf die Teufelshammer und ermöglicht es Euch, Krieger der Aschenzungen zu rekrutieren, die Eure Champions auf Missionen begleiten.\"" }
entries[138232] = { ["name"] = "Loramus Thalipedes", ["text"] = "\"Loramus Thalipedes kommt in Eure Ordenshalle und ermöglicht es Euch, Forschung für den Aufstiegsbaum des Ordens durchzuführen.\"" }
entries[138238] = { ["name"] = "Krabbenöl", ["text"] = "Questgegenstand\n\"Sicher, warum nicht?\"" }
entries[138239] = { ["name"] = "Intakter Krabbenpanzer", ["text"] = "Questgegenstand\n\"Vielleicht eine Schüssel? Möchte er eine Schüssel?\"" }
entries[138240] = { ["name"] = "Schnappende Krebsschere", ["text"] = "Questgegenstand\n\"Wenn man an diesem Punkt angelangt ist, lässt man nichts unversucht.\"" }
entries[138241] = { ["name"] = "Feiner Sand", ["text"] = "Questgegenstand\n\"Glatter, gleichmäßiger, aus dem Panzer geschüttelter Sand.\"" }
entries[138242] = { ["name"] = "Tarotkarten mit Wasserflecken", ["text"] = "Wird beim Aufheben gebunden\n\"Abergläubische Elfen waren überzeugt, diese Karten könnten einem die Zukunft offenbaren.\"\nVerkaufspreis:" }
entries[138243] = { ["name"] = "Rostzerfressenes Schwert", ["text"] = "Wird beim Aufheben gebunden\n\"Die Anzeichen uralter azsharischer Handwerkskunst lassen sich nur noch erahnen.\"\nVerkaufspreis:" }
entries[138244] = { ["name"] = "Verderbte Manaedelsteine", ["text"] = "Wird beim Aufheben gebunden\n\"Durch die Anwesenheit der Legion sind diese von den Nachtgeborenen bevorzugten 'Imbisse' verdorben.\"\nVerkaufspreis:" }
entries[138245] = { ["name"] = "Verdorbener azsharischer Weinschlauch", ["text"] = "Wird beim Aufheben gebunden\n\"Ein seltener Jahrgang, der aber etwas zu lange gereift hat.\"\nVerkaufspreis:" }
entries[138246] = { ["name"] = "Uralter eingelegter Koi", ["text"] = "Wird beim Aufheben gebunden\n\"Es gibt nur einen Weg, um festzustellen, ob dieser kleine Schatz erst letztes Jahr oder vor 10.000 Jahren eingelegt wurde. Soll jemand anderes ihn zuerst probieren.\"\nVerkaufspreis:" }
entries[138247] = { ["name"] = "Beschädigte Harfe", ["text"] = "Wird beim Aufheben gebunden\n\"Das bevorzugte Instrument adeliger Nachtgeborener, aber nichts für Grobmotoriker – wie man sieht.\"\nVerkaufspreis:" }
entries[138248] = { ["name"] = "Schweres Brultotem", ["text"] = "Wird beim Aufheben gebunden\n\"Wer hätte bei der rauen Natur der Drogbar eine solch exquisite und filigrane Arbeit erwartet?\"\nVerkaufspreis:" }
entries[138249] = { ["name"] = "Ruiniertes Zauberbuch", ["text"] = "Wird beim Aufheben gebunden\n\"Der Zahn der Zeit und die Elemente haben diesem Folianten sämtliche Geheimnisse entrissen.\"\nVerkaufspreis:" }
entries[138250] = { ["name"] = "Statue der Königin Azshara", ["text"] = "Wird beim Aufheben gebunden\n\"Eine wunderschöne Darstellung der Königin. Diese Statue ist viele Hundert Jahre alt.\"\nVerkaufspreis:" }
entries[138251] = { ["name"] = "Steinernes Drachenei", ["text"] = "Wird beim Aufheben gebunden\n\"Niemand kann sagen, ob dies ein echtes Drachenei ist, das vor langer Zeit aus einem Nest gestohlen wurde, oder einfach nur eine gemeißelte Replik.\"\nVerkaufspreis:" }
entries[138252] = { ["name"] = "Chronistin Elrianne", ["text"] = "\"Chronistin Elrianne kommt in Eure Ordenshalle und ermöglicht es Euch, Forschung für den Aufstiegsbaum des Ordens durchzuführen.\"" }
entries[138253] = { ["name"] = "Leywurmköder", ["text"] = "Questgegenstand\nBenutzen: Bedeckt Euch mit magiegetränkten Innereien.\n\"Eine klebrige Masse, die größtenteils aus Leywurminnereien besteht.\"" }
entries[138258] = { ["name"] = "Zügel des lang vergessenen Hippogryphen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren lang vergessenen Hippogryphen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur Ihr habt noch an ihn gedacht.\"\nZone:\nAzsuna" }
entries[138270] = { ["name"] = "Alptraumeichenholz", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieses kleine verdrehte und zersplitterte Stück Holz ist stabiler, als es aussieht.\"" }
entries[138271] = { ["name"] = "Phiole mit arkanem Wasser", ["text"] = "Questgegenstand\nEinzigartig\n\"Im Wasser wirbeln leuchtende arkane Energien.\"" }
entries[138272] = { ["name"] = "Khadgars Phiole", ["text"] = "Questgegenstand\nBenutzen: Dieser Behälter muss mit Wasser aus Azsharas Zorn gefüllt werden.\n\"Zur Befüllung mit magischem Wasser.\"" }
entries[138273] = { ["name"] = "Azurerz", ["text"] = "Questgegenstand\n\"Dieses Erz wird gelegentlich beim Abbau von Leystein aufgefunden und kann von begabten Schmieden zur Herstellung von Waffen verwendet werden.\"" }
entries[138274] = { ["name"] = "Kiste mit Azurwaffen", ["text"] = "Questgegenstand\nEinzigartig\n\"Voll mit Pfeilen, Munition und Speerspitzen, die von Schmied Kyriel hergestellt wurden.\"" }
entries[138285] = { ["name"] = "Blauflossenhäppchen", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 4250 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[138290] = { ["name"] = "Gegrillte Minirochen", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[138291] = { ["name"] = "Herber grüner Apfel", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Irgendwie ist Frau Boskop zu dieser neuen Sorte noch nicht der richtige Name eingefallen.\"\nVerkaufspreis:" }
entries[138292] = { ["name"] = "Leyreiches Wasser", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 5000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:" }
entries[138293] = { ["name"] = "Rucksack des Forschers", ["text"] = "18 Platz Tasche\nVerkaufspreis:" }
entries[138294] = { ["name"] = "Meeresbrise", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Ein echter Favorit unter den Challianeweinen – cremiger Abgang mit einem Hauch herber Tannine.\"\nVerkaufspreis:" }
entries[138295] = { ["name"] = "Farondis' königlicher Roter", ["text"] = "Benutzen: Ein ziemlich schwaches alkoholisches Getränk.\n\"Dieser im Auftrag der Familie Farondis gekelterte Challianewein ist ein komplexer Tropfen, der auch die höchsten Erwartungen erfüllt.\"\nVerkaufspreis:" }
entries[138296] = { ["name"] = "Glyptik der Hassnattern", ["text"] = "Questgegenstand\nHandwerksmaterial\n\"Ein kleiner geschnittener Edelstein, der als magischer Fokus genutzt wird.\"\nVerkaufspreis:" }
entries[138297] = { ["name"] = "Uralter Magiekern", ["text"] = "Questgegenstand\n\"Ein Energiekern, der aus uralter Elfenmagie geschaffen wurde.\"" }
entries[138299] = { ["name"] = "Uralte Knochen", ["text"] = "Questgegenstand\n\"Mit Schmutz und dem Gestank des Verfalls bedeckt.\"" }
entries[138300] = { ["name"] = "Gepäck des Wahnsinnigen", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\n34 Platz Tasche\n\"Ein seltsamer Behälter, dessen Volumen viel größer ist, als es sein dürfte.\"\nVerkaufspreis:" }
entries[138301] = { ["name"] = "Kontrollkugel", ["text"] = "Questgegenstand\nEinzigartig (20)" }
entries[138303] = { ["name"] = "Kiste mit verzauberten Azurwaffen", ["text"] = "Questgegenstand\nEinzigartig\n\"Voll mit Pfeilen, Munition und Speerspitzen, die von Lyana Sternenstaub verzaubert wurden.\"" }
entries[138307] = { ["name"] = "Verdorbener Stinkekäse", ["text"] = "Wird beim Aufheben gebunden\n\"Niemand weiß, wann genau er ungenießbar geworden ist, aber jetzt ist dieser Käse eindeutig verdorben.\"\nVerkaufspreis:" }
entries[138308] = { ["name"] = "Fläschchen Manawein", ["text"] = "Questgegenstand\n\"Kümmerlich klein, aber gefüllt mit den Hoffnungen und Träumen vieler.\"" }
entries[138309] = { ["name"] = "Handschuhe des Immerflammenwissens", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\n+ 4 Vielseitigkeit\nHaltbarkeit 55 / 55\nKlassen: Magier\nOrnat des Immerflammenwissens (0/6)\nHandschuhe des Immerflammenwissens\nKapuze des Immerflammenwissens\nGamaschen des Immerflammenwissens\nRobe des Immerflammenwissens\nMantel des Immerflammenwissens\nUmhang des Immerflammenwissens\nAltes Set: Bonus ist nicht aktiv\n(2) Set Arkan: Erhöht den von 'Arkane Geschosse' verursachten Schaden um 10%.\n(2) Set Feuer: Jede Anwendung von 'Verstärktes Feuerwerk' erhöht die kritische Trefferchance um zusätzlich 20%.\n(2) Set Frost: 'Frostblitz' hat eine um 5% erhöhte Chance, 'Hirnfrost' auszulösen.\n(4) Set Arkan: Das Wirken von 'Arkane Geschosse' verringert die verbleibende Abklingzeit von 'Hervorrufung' um 2.0 Sek.\n(4) Set Feuer: 'Kampfeshitze' hat zusätzlich eine Chance von 10%, Euch für 10 Sek. 15% Tempo zu gewähren.\n(4) Set Frost: Wenn 'Gefrorene Kugel' Schaden verursacht, hat der Effekt eine um 5% höhere Chance, 'Eisige Finger' auszulösen.\nVerkaufspreis:" }
entries[138310] = { ["name"] = "Handschuhe des Läuterers", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\n+ 2 Vielseitigkeit\nHaltbarkeit 55 / 55\nKlassen: Priester\nGewänder des Läuterers (0/6)\nHandschuhe des Läuterers\nKehlstück des Läuterers\nGamaschen des Läuterers\nSoutane des Läuterers\nMantel des Läuterers\nTuch des Läuterers\nAltes Set: Bonus ist nicht aktiv\n(2) Set Disziplin: Eure Heilung auf Zielen, die von Eurem 'Machtwort: Schild' betroffen sind, wird um 30% erhöht.\n(2) Set Heilig: Erhöht die Heilung von 'Echo des Lichts' aus 'Segenswort: Heiligung' um 100%.\n(2) Set Schatten: Jedes Mal, wenn 'Vampirberührung' Schaden verursacht, erzeugt die Fähigkeit 1 Wahnsinn.\n(4) Set Disziplin: Während 'Euphorie' aktiv ist, hält der von 'Machtwort: Schild' ausgelöste Effekt 'Abbitte' 6 Sek. länger an.\n(4) Set Heilig: Wenn das Ziel von Eurem 'Echo des Lichts' betroffen ist, wird die kritische Trefferchance von 'Segenswort: Epiphanie' um 20% erhöht.\n(4) Set Schatten: Nach dem Aktivieren der Leerengestalt wird die Abklingzeit von 'Leerenblitz' für 2.5 Sek. um 100% verringert.\nVerkaufspreis:" }
entries[138311] = { ["name"] = "Umklammerung von Azj'Aqir", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 55 / 55\nKlassen: Hexenmeister\nVermächtnis von Azj'Aqir (0/6)\nUmklammerung von Azj'Aqir\nAugen von Azj'Aqir\nGamaschen von Azj'Aqir\nPracht von Azj'Aqir\nSchulterstücke von Azj'Aqir\nUmhang von Azj'Aqir\nAltes Set: Bonus ist nicht aktiv\n(2) Set Gebrechen: 'Instabiles Gebrechen' verursacht 10% zusätzlichen regelmäßigen Schaden.\n(2) Set Dämonologie: Erhöht Euer Tempo um 3%.\n(2) Set Zerstörung: Der Einsatz von 'Chaosblitz' verringert für 4 Sek. die Zauberzeit Eures nächsten Einsatzes von 'Chaosblitz' um 10%.\n(4) Set Gebrechen: 'Agonie' hat eine um das 1,10-fache erhöhte Chance, einen Seelensplitter zu erzeugen.\n(4) Set Dämonologie: Schreckenspirscher halten 3 Sek. länger an.\n(4) Set Zerstörung: 'Feuersbrunst' erhält eine zusätzliche Aufladung, und die Abklingzeit wird um 2 Sek. verringert.\nVerkaufspreis:" }
entries[138312] = { ["name"] = "Kapuze des Immerflammenwissens", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 100 / 100\nKlassen: Magier\nOrnat des Immerflammenwissens (0/6)\nHandschuhe des Immerflammenwissens\nKapuze des Immerflammenwissens\nGamaschen des Immerflammenwissens\nRobe des Immerflammenwissens\nMantel des Immerflammenwissens\nUmhang des Immerflammenwissens\nAltes Set: Bonus ist nicht aktiv\n(2) Set Arkan: Erhöht den von 'Arkane Geschosse' verursachten Schaden um 10%.\n(2) Set Feuer: Jede Anwendung von 'Verstärktes Feuerwerk' erhöht die kritische Trefferchance um zusätzlich 20%.\n(2) Set Frost: 'Frostblitz' hat eine um 5% erhöhte Chance, 'Hirnfrost' auszulösen.\n(4) Set Arkan: Das Wirken von 'Arkane Geschosse' verringert die verbleibende Abklingzeit von 'Hervorrufung' um 2.0 Sek.\n(4) Set Feuer: 'Kampfeshitze' hat zusätzlich eine Chance von 10%, Euch für 10 Sek. 15% Tempo zu gewähren.\n(4) Set Frost: Wenn 'Gefrorene Kugel' Schaden verursacht, hat der Effekt eine um 5% höhere Chance, 'Eisige Finger' auszulösen.\nVerkaufspreis:" }
