entries[138371] = { ["name"] = "Schattenwickeltuch der Verdammnisklinge", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\n+ 4 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 2.\nKlassen: Schurke\nSchlachtrüstung der Verdammnisklinge (0/6)\nTunika der Verdammnisklinge\nStulpen der Verdammnisklinge\nGugel der Verdammnisklinge\nHosen der Verdammnisklinge\nSchiftung der Verdammnisklinge\nSchattenwickeltuch der Verdammnisklinge\nAltes Set: Bonus ist nicht aktiv\n(2) Set Meucheln: 'Verstümmeln' lässt zusätzlich das Ziel bluten und fügt ihm so im Verlauf von 8 Sek. 20% zusätzlichen Schaden zu.\n(2) Set Gesetzlosigkeit: Erhöht die Chance, dass 'Säbelhieb' 'Main Gauche' auslöst, um zusätzlich 30%.\n(2) Set Täuschung: Pro verbrauchtem Combopunkt hält 'Nachtklinge' zusätzlich 2 Sek. lang an.\n(4) Set Meucheln: Für jeden Eurer auf das Ziel wirkenden Blutungseffekte verursacht 'Vergiften' 7% mehr Schaden.\n(4) Set Gesetzlosigkeit: Es besteht eine Chance von 25%, dass durch 'Durchstoßen' Euer nächster Einsatz von 'Säbelhieb' keine Energie kostet. (Procchance: 25%)\n(4) Set Täuschung: Wenn Ihr 'Schattenschlag' gegen Ziele einsetzt, die von Eurer 'Nachtklinge' betroffen sind, besteht eine Chance von 30%, dass ein zusätzlicher Combopunkt erzeugt wird. (Procchance: 30%)\nVerkaufspreis:" }
entries[138372] = { ["name"] = "Umhang der gefesselten Elemente", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Schamane\nOrnat der gefesselten Elemente (0/6)\nStulpen der gefesselten Elemente\nHelm der gefesselten Elemente\nGamaschen der gefesselten Elemente\nGewandung der gefesselten Elemente\nSchulterstücke der gefesselten Elemente\nUmhang der gefesselten Elemente\nAltes Set: Bonus ist nicht aktiv\n(2) Set Elementar: Erhöht die kritische Trefferchance Eures Zaubers 'Blitzschlag' um 10%.\n(2) Set Verstärkung: Erhöht den Schaden von 'Sturmschlag' um 10%.\n(2) Set Wiederherstellung: 'Flutwellen' erhöht zusätzlich die hervorgerufene Heilung von 'Welle der Heilung' und 'Heilende Woge' um 15%.\n(4) Set Elementar: Erhöht Euren verursachten Naturschaden um 5%.\n(4) Set Verstärkung: Erhöht die Chance von 'Lavapeitsche', 'Sturmbringer' auszulösen, um 10%. (Procchance: 10%)\n(4) Set Wiederherstellung: Jedes Mal, wenn Ihr 'Flutwellen' auslöst, wird die Abklingzeit Eures Totems des heilenden Flusses um 3 Sek. verringert.\nVerkaufspreis:" }
entries[138373] = { ["name"] = "Umhang von Azj'Aqir", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 3 Vielseitigkeit\nKlassen: Hexenmeister\nVermächtnis von Azj'Aqir (0/6)\nUmklammerung von Azj'Aqir\nAugen von Azj'Aqir\nGamaschen von Azj'Aqir\nPracht von Azj'Aqir\nSchulterstücke von Azj'Aqir\nUmhang von Azj'Aqir\nAltes Set: Bonus ist nicht aktiv\n(2) Set Gebrechen: 'Instabiles Gebrechen' verursacht 10% zusätzlichen regelmäßigen Schaden.\n(2) Set Dämonologie: Erhöht Euer Tempo um 3%.\n(2) Set Zerstörung: Der Einsatz von 'Chaosblitz' verringert für 4 Sek. die Zauberzeit Eures nächsten Einsatzes von 'Chaosblitz' um 10%.\n(4) Set Gebrechen: 'Agonie' hat eine um das 1,10-fache erhöhte Chance, einen Seelensplitter zu erzeugen.\n(4) Set Dämonologie: Schreckenspirscher halten 3 Sek. länger an.\n(4) Set Zerstörung: 'Feuersbrunst' erhält eine zusätzliche Aufladung, und die Abklingzeit wird um 2 Sek. verringert.\nVerkaufspreis:" }
entries[138374] = { ["name"] = "Großumhang des Obsidianaspekts", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 4 Vielseitigkeit\nKlassen: Krieger\nKriegsplatte des Obsidianaspekts (0/6)\nBrustplatte des Obsidianaspekts\nStulpen des Obsidianaspekts\nKriegshelm des Obsidianaspekts\nBeinplatten des Obsidianaspekts\nSchulterplatten des Obsidianaspekts\nGroßumhang des Obsidianaspekts\nAltes Set: Bonus ist nicht aktiv\n(2) Set Waffen: Kritische Treffer mit 'Tödlicher Stoß' und 'Hinrichten' haben eine Chance von 10%, die Abklingzeit von 'Kolossales Schmettern' abzuschließen. (Procchance: 10%)\n(2) Set Furor: Erhöht Euren gesamten verursachten Schaden um 4%.\n(2) Set Schutz: Während 'Schildblock' aktiv ist, wird Eure Chance auf kritisches Blocken um 10% erhöht.\n(4) Set Waffen: Erhöht Euren gesamten verursachten Schaden um 4%.\n(4) Set Furor: Erhöht die Dauer Eurer Fähigkeit 'Wutanfall' um 1.0 Sek.\n(4) Set Schutz: Euer kritisches Blocken erzeugt 5 Wut. (1s Abklingzeit)\nVerkaufspreis:" }
entries[138375] = { ["name"] = "Cape des zweiten Gesichts", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nKlassen: Dämonenjäger\nGewänder des zweiten Gesichts (0/6)\nCape des zweiten Gesichts\nTunika des zweiten Gesichts\nHandschuhe des zweiten Gesichts\nMaske des zweiten Gesichts\nBeinwickel des zweiten Gesichts\nSchulterschutz des zweiten Gesichts\nAltes Set: Bonus ist nicht aktiv\n(2) Set Verwüstung: Der durch alle Eure Fähigkeiten erzeugte Jähzorn ist um 10% erhöht.\n(2) Set Rachsucht: 'Seelenspalter' erstattet 5 Schmerz. (500ms Abklingzeit)\n(4) Set Verwüstung: Erhöht die kritische Trefferchance für Euren 'Chaosstoß' um 8%.\n(4) Set Rachsucht: 'Seelenspalter' verringert die verbleibende Abklingzeit von 'Dämonenstachel' um bis zu 3 Sek., abhängig vom verbrauchten Schmerz.\nVerkaufspreis:" }
