entries[138441] = { ["name"] = "Groteske Überreste", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein Haufen aus orangefarbenem Schleim und Gebein... Sind das Dryadenknochen?\"" }
entries[138448] = { ["name"] = "Emblem von Margoss", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Teleportiert den Zaubernden zu Margoss' Idyll.\n\"Dieses Emblem hat sich anscheinend in Angelschnur verheddert.\"" }
entries[138450] = { ["name"] = "Signet von Sturmwind", ["text"] = "Wird beim Aufheben gebunden\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\n\"Wird den Helden der Allianz verliehen, die sich mutig in die Schlacht an der Verheerten Küste stürzen.\"\nVerkaufspreis:" }
entries[138451] = { ["name"] = "Vorlage: Tödlicher Tiefenbernstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch das Schleifen eines tödlichen Tiefenbernsteins.\nSchleift einen tödlichen Tiefenbernstein.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\nVerkaufspreis:\nTödlicher Tiefenbernstein\n+ 14 kritischer Trefferwert\nVerkaufspreis:\nBenötigt Tiefenbernstein" }
entries[138452] = { ["name"] = "Vorlage: Spiegelnder Azsunit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch das Schleifen eines spiegelnden Azsunits.\nSchleift einen spiegelnden Azsunit.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\nVerkaufspreis:\nSpiegelnder Azsunit\n+ 14 Tempo\nVerkaufspreis:\nBenötigt Azsunit" }
entries[138453] = { ["name"] = "Vorlage: Meisterlicher Königinnenopal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch das Schleifen eines meisterlichen Königinnenopals.\nSchleift einen meisterlichen Königinnenopal.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\nVerkaufspreis:\nMeisterlicher Königinnenopal\n+ 14 Meisterschaft\nVerkaufspreis:\nBenötigt Königinnenopal" }
entries[138454] = { ["name"] = "Vorlage: Tödliches Auge der Prophezeiung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein tödliches Auge der Prophezeiung herstellt.\nSchleift ein tödliches Auge der Prophezeiung.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\nVerkaufspreis:\nTödliches Auge der Prophezeiung\n+ 19 kritischer Trefferwert\nVerkaufspreis:\nBenötigt Auge der Prophezeiung , Blut von Sargeras" }
entries[138455] = { ["name"] = "Vorlage: Spiegelndes Morgenlicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein spiegelndes Morgenlicht herstellt.\nSchleift ein spiegelndes Morgenlicht.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\nVerkaufspreis:\nSpiegelndes Morgenlicht\n+ 19 Tempo\nVerkaufspreis:\nBenötigt Morgenlicht , Blut von Sargeras" }
entries[138456] = { ["name"] = "Vorlage: Meisterlicher Schattenrubin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen meisterlichen Schattenrubin herstellt.\nSchleift einen meisterlichen Schattenrubin.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\nVerkaufspreis:\nMeisterlicher Schattenrubin\n+ 19 Meisterschaft\nVerkaufspreis:\nBenötigt Schattenrubin , Blut von Sargeras" }
