entries[138477] = { ["name"] = "Reiner Wasserkern", ["text"] = "Questgegenstand\n\"Die Verderbnis hatte ihn noch nicht erwischt, als er entnommen wurde.\"" }
entries[138478] = { ["name"] = "Rippchenschmaus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Festmahl aus Rippchen her!\n\nStellt im Verlauf von 20 Sek. 5% Gesundheit und 5% Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10% Ausdauer.\n\nKann nur auf Schlachtfeldern verwendet werden.\nVerkaufspreis:" }
entries[138479] = { ["name"] = "Kartoffeleintopfschmaus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Festmahl aus Steak und Kartoffeln her!\n\nStellt im Verlauf von 20 Sek. 5% Gesundheit und 5% Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10% Ausdauer.\n\nKann nur auf Schlachtfeldern verwendet werden.\nVerkaufspreis:" }
entries[138480] = { ["name"] = "Foliant der Schwarzen Ernte", ["text"] = "Wird beim Aufheben gebunden\n\"Ein modriger Foliant, dessen Seiten mit Kritzeleien in einer uralten Sprache bedeckt sind.\"\nVerkaufspreis:" }
entries[138482] = { ["name"] = "Stattliche Seele", ["text"] = "Questgegenstand\n\"Sammelt genug davon, um den Sprungantrieb der Teufelshammer mit Energie zu versorgen.\"" }
entries[138483] = { ["name"] = "Teufelsmotoreinspritzdüse", ["text"] = "Questgegenstand\nEinzigartig\n\"Schön und gut, aber was genau wird da eingespritzt?\"" }
entries[138484] = { ["name"] = "Seelenkonfigurationsmatrix", ["text"] = "Questgegenstand\nEinzigartig\n\"Das ist alles ziemlich technisch und gleichzeitig auch magisch. Ihr solltet das wirklich den Profis überlassen – oder Jace.\"" }
entries[138485] = { ["name"] = "Umwandler für widerwärtige Geister", ["text"] = "Questgegenstand\nEinzigartig\n\"Was auch immer dieses Ding tut – gut ist es nicht. Zumindest tut es das nur widerwärtigen Geistern an. Sofern man dem Namen glauben darf.\"" }
entries[138486] = { ["name"] = "Dreiwindheiltrank", ["text"] = "Benutzen: Stellt 50% Gesundheit wieder her. Kann nur auf Schlachtfeldern verwendet werden. (5 Min Abklingzeit)\n\"Ein körniges, stinkendes Gemisch aus Riechsalz und sieben verschiedenen Gebräuen.\"\nVerkaufspreis:" }
entries[138487] = { ["name"] = "Shinfels Stab der Folter", ["text"] = "Wird beim Aufheben gebunden\n\"Eine bösartige Waffe, die von einem bösartigen Wesen benutzt wird.\"\nVerkaufspreis:" }
entries[138488] = { ["name"] = "Salzwassertrank", ["text"] = "Benutzen: Erhöht allen verursachten Schaden für 12 Sek. um 30%. Kann nur auf Schlachtfeldern verwendet werden.\n\"Destilliert aus den Tränen von Kämpfern, die einfach nicht mithalten konnten.\"\nVerkaufspreis:" }
entries[138490] = { ["name"] = "Wassersprechertotem", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Schamane\nBenutzen: Entfesselt das Wassersprechertotem, das Euch für 1 Stunde mit Wasserkugeln umgibt. Nur für Wiederherstellungsschamanen. (5 Min Abklingzeit)\n\"Wie die Visitenkarte eines großen Wiederherstellungsschamanen.\"\nVerkaufspreis:" }
