entries[138726] = { ["name"] = "Splitter der Potenzierung", ["text"] = "Artefaktmacht\nWird beim Aufheben gebunden\nBenutzen: Entdeckt die verborgene innere Kraft an der Schmiede in Eurer Klassenhalle, um Eurem Artefakt Macht zu verleihen.\n\nVerbraucht alle verfügbaren Gegenstände dieser Art." }
entries[138727] = { ["name"] = "Trank des Trotzes", ["text"] = "Benutzen: Verringert sämtlichen erlittenen Schaden 12 Sek. lang um 20%. Kann nur auf Schlachtfeldern verwendet werden. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[138728] = { ["name"] = "Trank der trivialen Unsichtbarkeit", ["text"] = "Benutzen: Macht für 6 Sek. unsichtbar. Kann nur auf Schlachtfeldern verwendet werden. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[138729] = { ["name"] = "Trank der geschärften Sinne", ["text"] = "Benutzen: Erhöht für 30 Sek. Eure Chance, unsichtbare oder verstohlene Gegner zu entdecken. Kann nur auf Schlachtfeldern verwendet werden. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[138730] = { ["name"] = "Synthebräubrille XL", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nKopf Kosmetisch\nAnlegen: Diese Brille simuliert die Effekte von Alkohol. Die Effekte können leicht entfernt werden, indem man die Brille absetzt.\n\"Achtung: Nicht beim Reiten benutzen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[138731] = { ["name"] = "Ein Scheffel Äpfel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Richtet für die Reittiere Eurer Gruppe oder Eures Schlachtzugs einen Scheffel Äpfel her!\n\nStellt im Verlauf von 20 Sek. pro Sekunde 5% Gesundheit und 5% Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und die Zauberzeit des Aufsitzens wird 1 Stunde lang um 50% verringert.\n\nKann nur auf Schlachtfeldern verwendet werden.\nVerkaufspreis:" }
entries[138732] = { ["name"] = "Geschichte der Klinge", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[138733] = { ["name"] = "Manipulator der Schattenschuppen", ["text"] = "Questgegenstand\nBenutzen: Hüllt einen Fliegenfresser der Schattenschuppen in eine temporale Abweichung, die ihn gefügig macht und ihn zum Zaubernden zieht, damit dieser ihn einsammeln kann. (6 Sek. Abklingzeit)" }
entries[138760] = { ["name"] = "Kommandantin Ansela", ["text"] = "Wird beim Aufheben gebunden\n\"Kommandantin Ansela kommt zur Kapelle des Hoffnungsvollen Lichts und ermöglicht es Euch, Knappentrupps zu rekrutieren, die Eure Champions auf Missionen begleiten.\"" }
entries[138761] = { ["name"] = "Sir Alamande Graudorn", ["text"] = "Wird beim Aufheben gebunden\n\"Sir Alamande Graudorn kommt in Eure Ordenshalle und ermöglicht es Euch, Forschung für den Aufstiegsbaum des Ordens durchzuführen.\"" }
