entries[138810] = { ["name"] = "Stachelrochenjunges", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Stachelrochenjunges beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Beschwörer Margoss\n- Guter Freund" }
entries[138811] = { ["name"] = "Gründling der salzigen Tiefen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr dieses Reittier herbeiruft. Kann nur in einer aquatischen Umgebung beschworen werden.\nBeschwört einen reitbaren Gründling der salzigen Tiefen oder gibt ihn wieder frei.\n\nLässt sich nur unter Wasser einsetzen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Beschwörer Margoss\n- Bester Freund\n\n\"Dieser scheue Fisch hält sich am liebsten zur Nahrungssuche in den tiefsten Tiefen des Großen Meeres auf.\"\nVerkäufer:\nBeschwörer Margoss\nZone:\nDalaran\nFraktion:\nBeschwörer Margoss - Wohlwollend\nKosten:\n100" }
