entries[138853] = { ["name"] = "Phiole mit Nachtbrunnenenergie", ["text"] = "Questgegenstand\nEinzigartig (50)\n\"Goldene und violette Wirbel brodeln heftig darin.\"" }
entries[138854] = { ["name"] = "Fragment des Kerkers des Verräters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Dämonenjäger\nAnlegen: Gewährt Euch 15% Lebensraub, während 'Dämonenstachel' aktiv ist.\n\"Zehntausend Jahre in Gefangenschaft. Verbannt aus meiner eigenen Heimat. Und nun wagt Ihr es, MEIN Reich zu betreten? Ihr wisst nicht, was Euch erwartet...\"\nVerkaufspreis:" }
