entries[138867] = { ["name"] = "Schimmerstarkbier", ["text"] = "Benutzen: Dieses Gebräu lässt den Trinkenden für 5 Min. schimmern und leuchten. Starker Alkohol.\nBenötigt Braufest\nVerkaufspreis:" }
