entries[138869] = { ["name"] = "Gordokbock", ["text"] = "Benutzen: Trinkt 5 Min. lang wie ein Oger. Starker Alkohol.\nBenötigt Braufest\nVerkaufspreis:" }
entries[138870] = { ["name"] = "Hochgeistige Weingeister", ["text"] = "Benutzen: Dieses Gebräu erlaubt nach dem Trinken für 5 Min. einen Einblick in das Geisterreich. Starker Alkohol.\nBenötigt Braufest\nVerkaufspreis:" }
