entries[138872] = { ["name"] = "Herbeirufer der Schwarzen Ernte", ["text"] = "\"Ein mächtiger Trupp, der Anhänger auf Missionen begleiten kann, um ihre Erfolgschance zu erhöhen.\"" }
entries[138873] = { ["name"] = "Mystischer Erstsemesterhut", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Entfesselt die auf den Hut gewirkte Verzauberung, um Eure Tage in der Akademie Revue passieren zu lassen. (6 Min Abklingzeit)" }
entries[138874] = { ["name"] = "Knisternde Splitter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Die Magie explodiert förmlich, sobald sie Eure Zunge berührt.\n\"Passt nicht zu Kaja'Cola.\"\nVerkaufspreis:" }
entries[138875] = { ["name"] = "Kleiner Leykristall", ["text"] = "Einzigartig (20)\n\"Die Verdorrten und die Nachtsüchtigen sammeln gerne kleinere Ausgaben hiervon als schnelle Lösung.\"" }
entries[138876] = { ["name"] = "Runas' Kristallschleifer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Mahlt kleine Leykristalle, die sich an den Leylinien Azsunas finden, zu halbwegs essbaren Kristallsplittern. Der Kristallschleifer benötigt nach jeder Sitzung etwas Zeit, bis er wieder verwendbar ist. (20 Std. Abklingzeit)\nVerkaufspreis:" }
entries[138877] = { ["name"] = "Formel: Foliant der Illusionen: Geheimnisse der Shado-Pan", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Folianten der Illusionen: Geheimnisse der Shado-Pan herstellt.\nStellt einen Folianten der Illusionen: Geheimnisse der Shado-Pan her.\nBenötigt Verzauberkunst der Verheerten Inseln (1)\nBenötigt Shado-Pan\n- Respektvoll\nVerkaufspreis:\nFoliant der Illusionen: Geheimnisse der Shado-Pan\nBenutzen: Sammelt die Waffenillusionsvorlagen 'Flussgesang' und 'Tanzender Stahl'.\nBenötigt Sha-Kristall (10), Chrysokoll (2), Rubellit (2), Goldberyll (2), Leichtes Pergament (3)" }
entries[138878] = { ["name"] = "Kopie von Daglops Vertrag", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Das Blut leuchtet von Zeit zu Zeit auf und gestattet Euch, Meister Daglop herbeizu... nein, zu \"bitten\", Euch einen Besuch abzustatten. (2 Std. Abklingzeit)" }
entries[138879] = { ["name"] = "Ovyds Winterhülle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Mönch\nAnlegen: Jedes Mal, wenn 'Einhüllender Nebel' heilt, hat der Heilungsbonus der Fähigkeit eine Chance von 50%, auf einen verletzten Verbündeten innerhalb von 30 Metern überzuspringen. (Procchance: 50%)\n\"Der Philosoph Ovyd ist einer der wenigen Vrykul in der gesamten Geschichte, die dem Schwert entsagten und stattdessen lieber auf die Macht der Worte setzten.\"\nVerkaufspreis:" }
entries[138880] = { ["name"] = "Entschlossenheit des Soldaten", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[138881] = { ["name"] = "Ruhm des Soldaten", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[138882] = { ["name"] = "Formel: Foliant der Illusionen: Draenor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Folianten der Illusionen: Draenor herstellt.\nStellt einen Folianten der Illusionen: Draenor her.\nBenötigt Verzauberkunst der Verheerten Inseln (1)\n\nFoliant der Illusionen: Draenor\nBenutzen: Sammelt die Waffenillusionsvorlagen 'Mal des Frostwolfs' und 'Mal des Donnerfürsten'.\nBenötigt Temporaler Kristall (20), Magische Luft (10), Magisches Wasser (10), Wildblut (15), Leichtes Pergament (3)" }
entries[138883] = { ["name"] = "Meryls herbeigezauberte Erfrischung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Wählt einen Eurer Trupps aus, um 1 Vitalität wiederherzustellen." }
entries[138884] = { ["name"] = "Wurfwurst", ["text"] = "Einzigartig (10)\nBenutzen: Wirft die Wurst einem freundlich gesinnten Spielercharakter zu. Falls er Platz in seinem Rucksack hat, wird er sie fangen!\nVerkaufspreis:" }
entries[138885] = { ["name"] = "Schatz der Zeitalter", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[138886] = { ["name"] = "Gunst der Valarjar", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[138892] = { ["name"] = "Königliches Siegel von Prinz Farondis", ["text"] = "Wird beim Aufheben gebunden\n\"Mögen sie eines Tages verstehen, warum ich tat, was ich getan habe.\"\nVerkaufspreis:" }
entries[138893] = { ["name"] = "Runas' letzte Kupfermünze", ["text"] = "Wird beim Aufheben gebunden\n\"Ich wünschte, ich hätte etwas Mana und zwar... jetzt! JETZT! Jetzt.\"\nVerkaufspreis:" }
entries[138894] = { ["name"] = "Stellagosas Silbermünze", ["text"] = "Wird beim Aufheben gebunden\n\"Bitte beschützt meinen Großvater.\"\nVerkaufspreis:" }
entries[138895] = { ["name"] = "Senegos' uralte Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Bitte helft meiner Enkelin, etwas lockerer zu werden.\"\nVerkaufspreis:" }
entries[138896] = { ["name"] = "Okuna Langhauers Dublone", ["text"] = "Wird beim Aufheben gebunden\n\"Das Abenteuer war beeindruckend, aber ich bin weit von Moa'ki entfernt. Ich möchte bald mein Zuhause sehen.\"\nVerkaufspreis:" }
entries[138897] = { ["name"] = "Des Knatzelfiddlers Flotschgroschen", ["text"] = "Wird beim Aufheben gebunden\n\"Was zum verfiddelten Nampuck? Was für'n fupfer-knatzeliger Nappelkuschler wirft 'ne blitzeblanke Münze weg?!\"\nVerkaufspreis:" }
entries[138898] = { ["name"] = "Münze von Golk, dem Grollen des Meeres", ["text"] = "Wird beim Aufheben gebunden\n\"Golk wünschte, Golk würde durch den Ausgang dieser Höhle passen.\"\nVerkaufspreis:" }
entries[138899] = { ["name"] = "Kupfermünze von Daglops Höllenbestie", ["text"] = "Wird beim Aufheben gebunden\n\"Ich wünschte, ich wäre etwas größer.\"\nVerkaufspreis:" }
entries[138900] = { ["name"] = "Gravil Goldzopfs berühmte Wurstzipfelmütze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Tragt den Hut. (10 Min Abklingzeit)\n\"Der einzige Fall, in dem es Wurst ist, was Ihr auf dem Kopf tragt.\"" }
entries[138901] = { ["name"] = "Tyrandes Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Auf dass ich die, die mir lieb und teuer sind, schützen und weiterhin die Erhabenheit und das Licht von Elune widerspiegeln mag.\"\nVerkaufspreis:" }
entries[138902] = { ["name"] = "Malfurions Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Waren wir zu spät, um den Alptraum aufzuhalten?\"\nVerkaufspreis:" }
entries[138903] = { ["name"] = "Kur'talos Rabenkrones geisterhafte Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Vielleicht kehrt wieder etwas Farbe in die Welt zurück, wenn wir diese endlose Flut von Dämonen eindämmen.\"\nVerkaufspreis:" }
entries[138904] = { ["name"] = "Jarod Schattensangs Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Gebt meinen Truppen die Stärke, die Prüfungen dieses Landes zu überstehen.\"\nVerkaufspreis:" }
entries[138905] = { ["name"] = "Penelope Heathrows Taschengeld", ["text"] = "Wird beim Aufheben gebunden\n\"Irgendwie wünschte ich, ich wäre ein Worgen. Wäre das nicht einfach super?\"\nVerkaufspreis:" }
entries[138906] = { ["name"] = "Remulos' Siegel", ["text"] = "Wird beim Aufheben gebunden\n\"Ich danke dem Zirkel des Cenarius. Mögen die sterblichen Druiden sich weiterhin des Namens meines Vaters würdig erweisen.\"\nVerkaufspreis:" }
entries[138907] = { ["name"] = "Elothirs goldenes Blatt", ["text"] = "Wird beim Aufheben gebunden\n\"Hmm... keine Münzen. Ob das hier reichen wird?\"\nVerkaufspreis:" }
entries[138908] = { ["name"] = "Kodas Siegel", ["text"] = "Wird beim Aufheben gebunden\n\"Ich glaube, mir könnte jetzt ein Klecks Honig schmecken.\"\nVerkaufspreis:" }
entries[138909] = { ["name"] = "König Mrgl-Mrgls Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Es gibt Tage, da glaube ich, dass die Murlocs nicht zu schätzen wissen, was ich alles für sie tue.\"\nVerkaufspreis:" }
entries[138910] = { ["name"] = "Hemet Nesingwarys Kugel", ["text"] = "Wird beim Aufheben gebunden\n\"Ich wünschte, mein Sohn würde sich beeilen und Kinder in die Welt setzen! Außerdem möchte ich einen Elch erlegen.\"\nVerkaufspreis:" }
entries[138911] = { ["name"] = "Murkys Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Mrr glrrrgl mrr glrrgl glrr.\"\nVerkaufspreis:" }
entries[138912] = { ["name"] = "Geistwandler Ebenhorns Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Für alle Brüder und Schwestern, die ich verloren habe.\"\nVerkaufspreis:" }
entries[138913] = { ["name"] = "Addie Zischmoors Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Ooh, ooh! Ich hoffe, ich kann mal mit einem echt tollen Gewehr schießen! BÄMM!\"\nVerkaufspreis:" }
entries[138914] = { ["name"] = "Bummbumm von Brullows Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Kommt schon, beweg den Panzer, Wusch! Genau wie wir es geübt haben!\"\nVerkaufspreis:" }
entries[138915] = { ["name"] = "Des Kerzenkönigs Kerzenmünze", ["text"] = "Wird beim Aufheben gebunden\n\"Ich will finden Kerzenkönigin! Hmm... Vielleicht hat Jackie Interesse? Ich ihr geben Kerze, dann weitersehen.\"\nVerkaufspreis:" }
entries[138916] = { ["name"] = "Torok Bluttotems Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Ich hasse alles. Alles ist schrecklich.\"\nVerkaufspreis:" }
entries[138917] = { ["name"] = "Gottkönig Skovalds teufelsbesudelte Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Stärke. Ruhm. Macht.\"\nVerkaufspreis:" }
entries[138918] = { ["name"] = "Genn Graumähnes Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Ein einziges gemeinsames Ziel löscht nicht die Gräueltaten aus, die von den Verlassenen verübt wurden.\"\nVerkaufspreis:" }
entries[138919] = { ["name"] = "Nathanos Pestrufers Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Dunkle Fürstin, wacht über diesen Brunnen.\"\nVerkaufspreis:" }
entries[138920] = { ["name"] = "Helyas Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Falls jemand diese Münze findet, möge er sie mir bitte zurückbringen... persönlich.\"\nVerkaufspreis:" }
entries[138921] = { ["name"] = "Sir Finley Mrrggltons Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Grundgütiger, ist das hier ein Wunschbrunnen? Wie entzückend.\"\nVerkaufspreis:" }
entries[138922] = { ["name"] = "Havis Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Igitt... Dieses Fleisch ist so trocken. Ich wünschte, ich hätte etwas Soße.\"\nVerkaufspreis:" }
entries[138923] = { ["name"] = "Vydhars Holzgroschen", ["text"] = "Wird beim Aufheben gebunden\n\"Sich mit Abenteurern zu unterhalten, ist so ermüdend... Ich möchte doch nur ein paar Jahrzehnte Frieden...\"\nVerkaufspreis:" }
entries[138924] = { ["name"] = "Rax Sechszünders goldbemalte Kupfermünze", ["text"] = "Wird beim Aufheben gebunden\n\"Reingelegt, blöder Brunnen.\"\nVerkaufspreis:" }
entries[138925] = { ["name"] = "Münze der Ersten Arkanistin Thalyssra", ["text"] = "Wird beim Aufheben gebunden\n\"Mögen die Geknechteten sich eines Tages erheben und den Platz derjenigen einnehmen, die sie einst unterdrückten.\"\nVerkaufspreis:" }
entries[138926] = { ["name"] = "Magistrix Elisandes Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Ich wünsche, mein Volk vor den bösen Fremden zu beschützen, die ihm schaden wollen. Koste es, was es wolle.\"\nVerkaufspreis:" }
entries[138927] = { ["name"] = "Oculeths Verschwindemünze", ["text"] = "Wird beim Aufheben gebunden\n\"Ach, hätte ich doch nur einen Lehrling, der mir folgen könnte!\"\nVerkaufspreis:" }
entries[138928] = { ["name"] = "Ly'leth Lunastres Familienwappen", ["text"] = "Wird beim Aufheben gebunden\n\"Ich wünschte, mein Vater wäre am Leben, um uns durch diese schwierigen Zeiten zu führen.\"\nVerkaufspreis:" }
entries[138929] = { ["name"] = "Perlenjäger Phins patschnasser Pfennig", ["text"] = "Wird beim Aufheben gebunden\n\"Gloooglrr mrm.\"\nVerkaufspreis:" }
entries[138930] = { ["name"] = "Berater Vandros' Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Behaltet Eure Wünsche für Euch. Ich verhandle nicht mit Brunnen.\"\nVerkaufspreis:" }
entries[138931] = { ["name"] = "Gul'dans Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Ich will nur, dass alle Welten brennen.\"\nVerkaufspreis:" }
entries[138932] = { ["name"] = "Jaulons Mal", ["text"] = "Wird beim Aufheben gebunden\n\"Ich will mehr Kätzchen.\"\nVerkaufspreis:" }
entries[138933] = { ["name"] = "Münze von Allari der Seelenfresserin", ["text"] = "Wird beim Aufheben gebunden\n\"Fische haben keine Seelen. Das hier ist zwecklos.\"\nVerkaufspreis:" }
entries[138934] = { ["name"] = "Münze von Altruis dem Leidenden", ["text"] = "Wird beim Aufheben gebunden\n\"Denkt selbst und macht Euch ein eigenes Bild.\"\nVerkaufspreis:" }
entries[138935] = { ["name"] = "Cyana Nachtgleves Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Ich wünschte, ich wäre stärker.\"\nVerkaufspreis:" }
entries[138936] = { ["name"] = "Falara Nachtweises Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Ich erinnere mich an die Zeit, als Suramar wunderschön und ruhig war... bevor Azshara und ihre Hochgeborenen alles zerstört haben. Wünsche bringen nur eines: Bedauern.\"\nVerkaufspreis:" }
entries[138937] = { ["name"] = "Izal Weißmonds Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Magier ließen mich hier landen. Die meisten betrachten einen mit Argwohn, Abscheu oder Schlimmerem, doch manche können über Äußerlichkeiten hinwegsehen. Ich wünsche mir, dass wir alle zusammen gegen unseren wahren Feind stehen: die Brennende Legion.\"\nVerkaufspreis:" }
entries[138938] = { ["name"] = "Jace Düsterwebers Münze", ["text"] = "Wird beim Aufheben gebunden\n\"In meinem früheren Leben hätte ich liebend gern all meine Zeit in diesem schwebenden Wunder verbracht. Den ganzen Tag hätte ich entweder in diesem magischen Brunnen geangelt oder mich in den arkanen Künsten geübt. Diese Zeiten sind längst vorbei.\"\nVerkaufspreis:" }
entries[138939] = { ["name"] = "Kayn Sonnenzorns Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Nur mit einer starken Führung und einer klaren Sicht der Dinge erringt man den Sieg.\"\nVerkaufspreis:" }
entries[138940] = { ["name"] = "Kor'vas Blutdorns Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Angeln und Wünschen? Den Luxus kann ich mir nicht leisten. Es gibt immer noch Dämonen, die ich töten muss.\"\nVerkaufspreis:" }
entries[138941] = { ["name"] = "Die Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Erhaltet 1 Manakristall nur für diesen Zug.\"\nVerkaufspreis:" }
entries[138942] = { ["name"] = "Blingtrons Botmünze", ["text"] = "Wird beim Aufheben gebunden\n\"Das Wunschmodul ist aktuell ausgelastet. Bitte versucht es später erneut. (Fehler 37)\"\nVerkaufspreis:" }
entries[138943] = { ["name"] = "Lady Liadrins Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Möge das Licht dieses Land in all seiner Herrlichkeit erleuchten.\"\nVerkaufspreis:" }
entries[138944] = { ["name"] = "Lunaras Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Was ist der Ruf der Natur? Ich wünschte wirklich, mir würde mal jemand erklären, was 'Ruf der Natur' eigentlich bedeutet.\"\nVerkaufspreis:" }
entries[138945] = { ["name"] = "Illidans Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Auf das Ende der Brennenden Legion.\"\nVerkaufspreis:" }
entries[138946] = { ["name"] = "Königliches Siegel von Königin Azshara", ["text"] = "Wird beim Aufheben gebunden\n\"Bald schon werdet Ihr ALLE meinen Zorn zu spüren bekommen!!!\"\nVerkaufspreis:" }
entries[138947] = { ["name"] = "Gallywix' Münze an der Schnur", ["text"] = "Wird beim Aufheben gebunden\n\"Ja! So erfüllt sich mein Wunsch UND ich kann meine Münze behalten. Ha! Oh, nein! Die Schnur ist gerissen! Dämlicher Brunnen, gib mir sofort meine Münze wieder...\"\nVerkaufspreis:" }
entries[138948] = { ["name"] = "Li Lis Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Ich wünsche mir, dass immer wieder neue Kontinente entdeckt werden, die ich erforschen kann.\"\nVerkaufspreis:" }
entries[138949] = { ["name"] = "Kirel narak", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\n+ 3 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Dämonenjäger\nAnlegen: Der Initialschaden von 'Feuerbrandaura' verringert die verbleibende Abklingzeit von 'Flammendes Brandmal' für jeden getroffenen Gegner um 2 Sek.\n\"Vergeht in den Flammen, die zahllose Welten verschlungen haben. Alles muss im Feuer der Legion verbrennen!\"\nVerkaufspreis:" }
entries[138951] = { ["name"] = "Überrest des Feuers", ["text"] = "Questgegenstand\n\"Beweis für Eure Befehlsgewalt über das Element Feuer.\"" }
entries[138952] = { ["name"] = "Überrest der Luft", ["text"] = "Questgegenstand\n\"Beweis für Eure Befehlsgewalt über das Element Luft.\"" }
entries[138953] = { ["name"] = "Überrest des Wassers", ["text"] = "Questgegenstand\n\"Beweis für Eure Befehlsgewalt über das Element Wasser.\"" }
entries[138954] = { ["name"] = "Illusion: Vergiftet", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: Sammelt die Waffenillusionsvorlage 'Vergiftet'.\nVerkaufspreis:" }
entries[138955] = { ["name"] = "Illusion: Rune des schneidenden Eises", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Todesritter\nBenutzen: Sammelt die Waffenillusionsvorlage 'Rune des schneidenden Eises'.\nVerkaufspreis:" }
entries[138956] = { ["name"] = "Hypermagnetischer Köder", ["text"] = "Einzigartig\nBenutzen: Befestigt den Köder an Eurer Angelrute. Er kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:" }
entries[138957] = { ["name"] = "Auriphage Sardine", ["text"] = "Einzigartig\nBenutzen: Befestigt den münzfressenden Fisch an Eurer Angelrute. Er kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:" }
entries[138958] = { ["name"] = "Klecks echt klebrigen Leims", ["text"] = "Einzigartig\nBenutzen: Bringt den Kleber an Eurem Angelhaken an. Er kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:" }
entries[138959] = { ["name"] = "Mikrovortexgenerator", ["text"] = "Einzigartig\nBenutzen: Befestigt das Gerät an Eurer Angelrute, das an Eurem Angelort einen kleinen Strudel erzeugt. Es kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:" }
entries[138960] = { ["name"] = "Wunschkristall", ["text"] = "Einzigartig\nBenutzen: Befestigt den Kristall an Eurer Angelrute. Einige Angler der Draenei glauben, dies würde beim Angeln von Münzen aus Springbrunnen helfen.\nVerkaufspreis:" }
entries[138961] = { ["name"] = "Alchemistisches Haftmittel", ["text"] = "Einzigartig\nBenutzen: Verteilt das Haftmittel auf Eurem Angelhaken, sodass er sich besser mit Metall verbindet. Das kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:" }
entries[138962] = { ["name"] = "Seestern mit Faden", ["text"] = "Einzigartig\nBenutzen: Bindet den Seestern an Eure Angelrute. Er kann Euch mit seinen Saugnäpfen dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:" }
entries[138963] = { ["name"] = "Winzig kleines Greifgerät", ["text"] = "Einzigartig\nBenutzen: Befestigt den Apparat an Eurer Angelrute. Er kann Euch dabei behilflich sein, gewisse Münzen aus dem Springbrunnen von Dalaran zu angeln.\nVerkaufspreis:" }
entries[138965] = { ["name"] = "Zauberstab des Entzugs", ["text"] = "Questgegenstand\nBenutzen: Entzieht den Leichen der Nachtgeborenen in Suramar Nachtbrunnenenergie. (5 Sek. Abklingzeit)" }
entries[138966] = { ["name"] = "Bergbeeren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kann beim Verzehr minimale Sättigung gewähren.\n\"Farbenfrohe Früchte, die am Hochberg wachsen und einen beißenden Geruch verbreiten.\"" }
entries[138967] = { ["name"] = "Großer Brunnengoldfisch", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 2550 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
